This tutorial uses one question throughout:

> How do I stream intermediate tool results from a subagent?

Pass that question to a [Deep Agent](/oss/javascript/deepagents/overview) with no custom tools and no access to the documentation corpus, to see what the model comes up with:

<CodeGroup>
  ```ts Google theme={"theme":{"light":"catppuccin-latte","dark":"catppuccin-mocha"}}
  import "dotenv/config";

  import { createDeepAgent } from "deepagents";
  import { HumanMessage } from "langchain";

  const EXAMPLE_QUERY =
    "How do I stream intermediate tool results from a subagent?";

  const baselineAgent = createDeepAgent({
    model: "google-genai:gemini-3.6-flash",
    tools: [],
    systemPrompt:
      "You are a helpful LangChain documentation assistant. Answer questions about LangChain APIs and patterns.",
  });

  const result = await baselineAgent.invoke({
    messages: [new HumanMessage(EXAMPLE_QUERY)],
  });

  console.log(result.messages.at(-1)?.text);
  ```

## Tool calls

When subagents use tools, you can stream tool call events to display what each subagent is doing. Tool call chunks appear in the `messages` stream mode.

```ts theme={"theme":{"light":"catppuccin-latte","dark":"catppuccin-mocha"}}
import { AIMessageChunk, ToolMessage } from "langchain";

for await (const [namespace, chunk] of await agent.stream(
  {
    messages: [
      {
        role: "user",
        content: "Research recent quantum computing advances",
      },
    ],
  },
  { streamMode: "messages", subgraphs: true },
)) {
  const [message] = chunk;

  // Identify source: "main" or the subagent namespace segment
  const isSubagent = namespace.some((s: string) => s.startsWith("tools:"));
  const source = isSubagent
    ? namespace.find((s: string) => s.startsWith("tools:"))!
    : "main";

# ─── Phase 3: Detect subagent completing ──────────────────────
            # When the main agent's tools node returns a tool message,
            # the subagent has completed and returned its result.
            if not chunk["ns"] and node_name == "tools":
                for msg in data.get("messages", []):
                    if msg.type == "tool":
                        sub = active_subagents.get(msg.tool_call_id)
                        if sub:
                            sub["status"] = "complete"
                            print(
                                f'[lifecycle] COMPLETE → subagent "{sub["type"]}" '
                                f"({msg.tool_call_id})"
                            )
                            print(f"  Result preview: {str(msg.content)[:120]}...")

# Print final state
print("\n--- Final subagent states ---")
for sub_id, sub in active_subagents.items():
    print(f"  {sub['type']}: {sub['status']}")
